<template><main class="page checkout-page"><header class="topbar"><button class="icon-button" @click="router.back()"><AppIcon name="arrow-left" /></button><h1>确认订单</h1><button class="icon-button"><AppIcon name="more" /></button></header><section class="checkout-timing"><div class="safe-bar"><span><AppIcon name="shield-check" size="15" /> Venuo 官方安全交易保障</span><b><AppIcon name="clock" size="13" /> 提交后开始计时</b></div><p class="payment-window-note">{{ paymentWindowText }}</p></section><div class="container checkout"><section class="card event-summary"><div class="mini-cover"><ActivityCover :src="selection?.activity?.coverFileUrl || ''" :title="selection?.activity?.title || '活动'" /><span>电子验票</span></div><div><h2>{{ selection?.activity?.title || '活动订单' }}</h2><p><AppIcon name="calendar" size="15" /> {{ format(selection?.session?.startTime || selection?.activity?.startTime) }}</p><p><AppIcon name="pin" size="15" /> {{ selection?.activity?.venueName || '场地待定' }}</p><div class="ticket-summary"><small>票品规格</small><b>{{ selection?.ticket?.name || '已选票种' }} × {{ selection?.quantity || 0 }}张</b></div></div></section><section class="card identity-block"><h2>实名信息 <RouterLink to="/profile?identity=1&amp;returnTo=/orders/confirm">填写 / 修改 ›</RouterLink></h2><div class="identity-inner"><strong>{{ profile?.realName || '尚未填写实名信息' }} <em v-if="profile?.realNameVerified">已填写</em></strong><p>证件号码 <span>{{ profile?.idCardMasked || '未填写' }}</span></p><p>手机号码 <span>{{ profile?.phone?.replace(/^(\d{3})\d{4}(\d{4})$/, '$1****$2') || '未绑定手机号' }}</span></p><b>入场时需提供核销码及与本订单一致的身份证号。</b></div></section><section class="card scan-tip"><span><AppIcon name="qr" size="24" /></span><div><b>手机扫码入场 · 实名电子票</b><p>支付成功后发放电子票至【我的订单/我的票夹】</p></div></section><section class="card order-block"><h2>费用明细</h2><div class="line-item"><span>票面总价</span><span>¥{{ total }}</span></div><div class="coupon-select"><label for="orderCoupon"><AppIcon name="ticket" size="15" /> 优惠券 <RouterLink to="/coupons">去领取</RouterLink></label><select id="orderCoupon" v-model="selectedCouponId" :disabled="couponsLoading || loading"><option value="">{{couponsLoading?'正在加载优惠券…':'不使用优惠券'}}</option><option v-for="item in couponChoices" :key="item.coupon.id" :value="String(item.coupon.id)" :disabled="!item.usable">{{item.coupon.name}} · {{item.usable ? '减 ¥'+Number(item.discountAmount).toFixed(2) : item.reason}}</option></select><p v-if="couponError">{{couponError}} <button type="button" @click="loadCoupons">重试</button></p></div><div v-if="discount>0" class="line-item discount"><span>优惠券抵扣</span><span>-¥{{discount.toFixed(2)}}</span></div><hr><div class="amount-line"><b>预计实付金额</b><strong>¥{{ payTotal }}</strong></div></section><section class="card payment-block"><h2>支付方式</h2><div class="payment selected"><span class="wechat-mark"><AppIcon name="wechat" size="25" /></span><span>微信支付（模拟，不发生真实扣款）</span><b><AppIcon name="check" size="14" /></b></div></section><label class="agreement"><input v-model="agreementAccepted" type="checkbox"> 我已阅读并同意《观演人须知及退改规则》和《个人信息保护与电子票使用声明》</label><div v-if="error" class="state-card error card"><b>订单提交失败</b><p>{{ error }}</p><button class="secondary-button" @click="submit">重新提交</button></div></div><div class="submit-dock"><div><small>支付：<strong>¥{{ payTotal }}</strong></small><a>明细⌃</a></div><button class="primary-button" :disabled="!selection || loading || !profile?.realNameVerified || !agreementAccepted" @click="submit"><AppIcon name="wechat" size="16" /> {{ loading ? '提交中...' : '提交订单并支付' }}</button></div></main></template>
<style scoped>.mini-cover .activity-cover{position:absolute;inset:0;border-radius:inherit}
.identity-block h2 a{float:right;font-size:13px;font-weight:400;color:var(--primary)}
.submit-dock{bottom:64px}.checkout{padding-bottom:190px}.checkout-page{min-height:100vh;overflow-y:auto;scroll-padding-bottom:190px}.wechat-mark{width:30px;height:30px;display:grid;place-items:center;color:#1aad19}
</style>
<script setup>
import { computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useOrderStore } from '../../stores/order'
import AppIcon from '../../components/AppIcon.vue'
import ActivityCover from '../../components/ActivityCover.vue'
import { orderIdOf } from '../../utils/id'
import { profileApi } from '../../api/profile'
import { couponApi } from '../../api/coupon'
import { orderApi } from '../../api/order'
const store=useOrderStore(),router=useRouter(),selection=computed(()=>store.selection),loading=ref(false),error=ref(''),profile=ref(null),agreementAccepted=ref(false)
import { ref } from 'vue'
const paymentWindowSeconds=ref(null)
const paymentWindowText=computed(()=>paymentWindowSeconds.value ? `订单生成后，需在 ${Math.floor(paymentWindowSeconds.value/60)} 分钟内完成支付，超时自动关闭。` : '提交订单后开始支付倒计时，具体截止时间以支付页面为准。')
async function loadPaymentPolicy(){try{const policy=await orderApi.paymentPolicy();const seconds=Number(policy?.paymentTimeoutSeconds);if(Number.isFinite(seconds)&&seconds>0)paymentWindowSeconds.value=seconds}catch{paymentWindowSeconds.value=null}}
onMounted(loadPaymentPolicy)
const total=computed(()=>((Number(selection.value?.ticket?.price)||0)*(selection.value?.quantity||0)).toFixed(2))
const couponChoices=ref([]),selectedCouponId=ref(''),couponsLoading=ref(false),couponError=ref('')
const discount=computed(()=>Number(couponChoices.value.find(x=>String(x.coupon.id)===selectedCouponId.value && x.usable)?.discountAmount || 0))
const payTotal=computed(()=>(Number(total.value)-discount.value).toFixed(2))
async function loadCoupons(){
 if(!selection.value?.ticketTypeId)return
 couponsLoading.value=true;couponError.value='';selectedCouponId.value=''
 try{couponChoices.value=await couponApi.choices(selection.value.ticketTypeId,selection.value.quantity)||[]}
 catch(e){couponError.value=e.message||'优惠券加载失败，可重试或不使用优惠券'}finally{couponsLoading.value=false}
}
async function submit(){if(!profile.value?.realNameVerified){error.value='请先在“我的”页面完成实名信息';return}if(!agreementAccepted.value){error.value='请先阅读并同意相关协议';return}loading.value=true;error.value='';try{const order=await store.createOrder(selectedCouponId.value || null);const id=orderIdOf(order);if(!id)throw new Error('创建订单成功，但未返回订单编号');router.replace(`/orders/pay/${id}`)}catch(e){error.value=e.message||'订单提交失败'}finally{loading.value=false}}
function format(v){return v?String(v).replace('T',' ').replace(/([+-]\d\d:\d\d|\.\d+Z?)$/,''):'时间待定'}
onMounted(loadCoupons)
onMounted(async()=>{try{profile.value=await profileApi.get()}catch{profile.value=null}})
</script>
