item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;font-size:14px}.line-item em{font-style:normal;color:#087d5d;background:#e3f6ee;padding:3px 5px;font-size:10px}.discount{color:#b45309}.order-block hr{border:0;border-top:1px solid var(--line);margin:11px 0}.amount-line{display:flex;justify-content:space-between;align-items:baseline}.amount-line strong{font-size:27px;color:var(--primary)}.payment{width:100%;display:flex;align-items:center;gap:14px;border:0;background:#f0f3ff;border-radius:10px;min-height:62px;margin:10px 0;padding:0 16px;color:var(--primary);font-size:23px}.payment span{color:#0f172a;font-size:17px}.payment .wechat-mark{color:#1aad19;font-size:inherit}.payment small{background:#ffeadc;color:#b45309;padding:3px 7px;border-radius:8px;font-size:10px}.payment b{margin-left:auto;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#dbe4ff;color:#fff;font-size:14px}.payment.selected{background:#dfe6ff}.payment.selected b{background:var(--primary)}.agreement{display:block;margin:18px 6px;color:var(--primary);font-size:13px;line-height:1.5}.agreement input{accent-color:var(--primary);margin-right:7px}.state-card{padding:18px;text-align:center;margin:15px 0}.state-card p{color:var(--muted)}.submit-dock{position:fixed;bottom:64px;left:0;right:0;background:#fff;border-top:1px solid var(--line);padding:8px max(16px,calc((100% - 780px)/2 + 16px)) calc(8px + env(safe-area-inset-bottom));display:flex;align-items:center;justify-content:space-between;z-index:15}.submit-dock small{display:block;color:var(--muted);font-size:12px}.submit-dock small strong{font-size:22px;color:var(--primary)}.submit-dock a{display:block;color:var(--muted);font-size:10px}.submit-dock .primary-button{min-width:190px}.safe-bar{display:flex;align-items:center;gap:5px}.safe-bar b{display:inline-flex;align-items:center;gap:3px;margin-left:auto;float:none}.event-summary p{display:flex;align-items:center;gap:5px}.line-item>span:first-child{display:inline-flex;align-items:center;gap:4px}.payment>span{display:inline-flex;align-items:center}.submit-dock button{display:inline-flex;align-items:center;justify-content:center;gap:6px}.submit-dock a{display:inline-flex;align-items:center;gap:2px}</style>



<style scoped>.coupon-select{padding:12px 0}.coupon-select label{display:flex;align-items:center;gap:6px;font-size:14px;margin-bottom:10px}.coupon-select label a{margin-left:auto;color:var(--primary);font-size:12px}.coupon-select select{width:100%;border:1px solid #dce4f2;border-radius:8px;background:#f8faff;padding:11px 8px;color:#334b6e;min-width:0}.coupon-select p{font-size:12px;color:#bd4556}.coupon-select p button{border:0;background:none;color:var(--primary)}</style>

